public static int digitSum(int num) {
    int sum = 0;
    while (num > 0) {
        sum = sum + num % 10;
        num = num / 10;
    }
    return sum;
}

public static int maxDigitSum(int[] nums) {
    int best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        // רק גדול ממש: בתיקו נשאר המספר הראשון
        if (digitSum(nums[i]) > digitSum(best)) {
            best = nums[i];
        }
    }
    return best;
}

public static int minDigitSum(int[] nums) {
    int best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        // רק קטן ממש: בתיקו נשאר המספר הראשון
        if (digitSum(nums[i]) < digitSum(best)) {
            best = nums[i];
        }
    }
    return best;
}

